"""Register A Breath of Change (World Bank, 2025) findings: sources S182-S183, claims C227+, extraction register.

Run once: python3 research/analysis/add_boc.py   (guarded: exits if C227 already exists)
Page convention: printed page numbers are cited publicly (roman for the overview); PDF page = printed page + 52 for chapters.
Every row was written while reading the owner-supplied PDF (sources/private/, git-ignored, copyright World Bank).
"""
import csv, os, sys
D = os.path.join(os.path.dirname(__file__), "..", "data"); R = os.path.join(os.path.dirname(__file__), "..")
claims = list(csv.DictReader(open(os.path.join(D, "claims.csv"))))
if any(c["claim_id"] == "C227" for c in claims): sys.exit("already registered")
def app(f, row):
    with open(os.path.join(D, f), "a", newline="") as fh: csv.writer(fh, lineterminator="\n").writerow(row)
app("sources.csv", ["S182", "A Breath of Change: Solutions for Cleaner Air in the Indo-Gangetic Plains and Himalayan Foothills", "Heger MP, Cros M, Pople A (eds.), World Bank",
    "World Bank Group", "2025-12", "https://www.worldbank.org/en/region/sar/publication/a-breath-of-change-solutions-for-cleaner-air-in-the-indo-gangetic-plains-and-himalayan-foothills",
    "2026-11-23", "organisational-report", "en", "full-text-read", "Owner-supplied PDF read in full-text form; cited by printed page (overview in roman numerals; PDF page = printed + 52 in chapters). Copyright World Bank; not redistributed. Synthesises upstream studies: upstream results are cited as reported by the book."])
app("sources.csv", ["S183", "Can Pollution Markets Work in Developing Countries? Experimental Evidence from India", "Greenstone M, Pande R, Ryan N, Sudarshan A",
    "Quarterly Journal of Economics 140(2) (paper copy hosted by the World Bank)", "2025-05", "https://thedocs.worldbank.org/en/doc/43a1279f2bd4fd555add4e7e59b0644b-0050022025/original/CAN-POLLUTION-MARKETS-WORK-IN-DEVELOPING-COUNTRIES.pdf",
    "2026-11-23", "primary-study", "en", "full-text-read", "Primary randomised evaluation of the Surat particulate emissions trading scheme; checked because the book reports two different results."])
# (claim_id, text, sources, locator, evidence_type, geography, period, chapter, printed, pdf, kind, overlap, relation, site_use, verify)
